CREATE DEFINER=`root`@`10.3.39.14` PROCEDURE `getselectedplayerListfrmmandal` (IN `distcode` INT)   BEGIN
    SELECT 
        mm.MandalName, 
        pd.player_reg_id, 
        pd.player_nm, 
        pd.father_nm, 
        CASE 
            WHEN pd.gender = 1 THEN 'Male' 
            ELSE 'Female' 
        END AS Gender, 
        pd.player_age, 
        pd.dob, 
        pd.mobile_no, 
        gd.game_sub_type, 
        dis.dist_game_nm,
        (
            SELECT evt.event_name 
            FROM tb_events evt 
            WHERE evt.id = ed.event_id 
              AND evt.discipline_id = ed.discipline_id
        ) AS event_name
    FROM 
        player_details pd
    JOIN 
        tb_game_details gd ON gd.player_id = pd.id
    JOIN 
        tb_discpline dis ON dis.game_id = gd.game_type
    JOIN 
        tb_event_details ed ON ed.player_id = gd.player_id 
                            AND ed.discipline_id = gd.game_type  
                            AND ed.is_district_level = 1
    JOIN 
        mandalmaster mm ON mm.ID = pd.mandal_id
    WHERE 
        pd.district_id = distcode 
        AND pd.player_reg_id IS NOT NULL
    ORDER BY 
        gd.game_type;
END$$

CREATE DEFINER=`root`@`10.3.39.14` PROCEDURE `insert_player_from_old` (IN `p_limit` INT)   BEGIN
    DECLARE v_rand_id INT;
    DECLARE v_primary_id INT;

    DECLARE v_district_id INT;
    DECLARE v_mandal_id INT;
    DECLARE v_village_id INT;
    DECLARE v_cluster_id INT;
    DECLARE v_game_id INT;
    DECLARE old_data_id INT;

    DECLARE i INT DEFAULT 1;

    /* Handler to avoid SELECT ... INTO errors */
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    BEGIN
        SET v_district_id = NULL;
        SET v_mandal_id   = NULL;
        SET v_village_id  = NULL;
        SET v_cluster_id  = NULL;
    END;

    WHILE i <= p_limit DO

        /* Generate next primary_id */
        SELECT IFNULL(MAX(primary_id), 0) + 1
        INTO v_primary_id
        FROM player_details;

        /* Random village ID */
        SET v_rand_id = FLOOR(1 + RAND() * 12796);

        /* Random old data ID */
        SET old_data_id = FLOOR(1 + RAND() * 226023);

        /* Fetch village details */
        SELECT 
            distNo,
            mandalNo,
            ID,
            cluster_id
        INTO
            v_district_id,
            v_mandal_id,
            v_village_id,
            v_cluster_id
        FROM villagemaster
        WHERE ID = v_rand_id
        LIMIT 1;

        /* Random game */
        SELECT game_id
        INTO v_game_id
        FROM tb_discpline
        ORDER BY RAND()
        LIMIT 1;

        /* Insert one player */
            primary_id,
            game_id,
            event_id,
            player_cat_id,
            player_nm,
            father_nm,
            gender,
            dob,
            player_age,
            mobile_no,
            aadhar,
            register_type,
            district_id,
            mandal_id,
            village_id,
            urban_id,
            venue_id,
            assembly_id,
            cat_id,
            player_reg_id,
            age_proof,
            history_games,
            reg_by,
            vill_GP_Name,
            user_id,
            cluster_id,
            player_email
        )
        SELECT
            v_primary_id,
            v_game_id,
            0,
            1,
            player_nm,
            father_nm,
            gender,
            dob,
            player_age,
            generateNewMobileNum(),
            generateuid(),
            1,
            v_district_id,
            v_mandal_id,
            v_village_id,
            urban_id,
            venue_id,
            0,
            cat_id,
            player_reg_id,
            age_proof,
            history_games,
            reg_by,
            vill_GP_Name,
            user_id,
            v_cluster_id,
            '-'
        FROM cmcup_db.player_details
        WHERE id = old_data_id
        LIMIT 1;

        SET i = i + 1;

    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_batch_creation` (IN `player_id` INT(11), IN `gameid` INT(11), IN `venueid` INT(10), IN `team_id` INT(10), IN `player_name` VARCHAR(100), IN `gender` VARCHAR(50), IN `EventID` INT(10))  NO SQL BEGIN
    DECLARE l_TeamNo INT DEFAULT NULL;
    DECLARE l_TeamCount INT;
    DECLARE l_GameType INT;
    DECLARE l_EventSize INT;
    DECLARE l_TeamSize INT;
    DECLARE done INT DEFAULT FALSE;
    DECLARE l_Team_nm INT;
    DECLARE l_TotalPlayers INT;

  
    DECLARE order_cursor CURSOR FOR
        SELECT team_nm, COUNT(*) 
        FROM tb_selected_players 
        WHERE game_id = gameid 
          AND Event_ID = EventID 
          AND Venue_id = venueid 
        GROUP BY team_nm 
        ORDER BY team_nm;
        
DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    SET l_GameType = (SELECT is_Team FROM tb_discpline WHERE game_id = gameid);

    
    SET l_TeamSize = (SELECT team_size + extra_players FROM tb_discpline WHERE game_id = gameid);

    
    OPEN order_cursor;

    
    read_loop: LOOP
        FETCH order_cursor INTO l_Team_nm, l_TotalPlayers;
        IF done THEN
            LEAVE read_loop;
        END IF;

        
        IF (l_TotalPlayers < l_TeamSize) THEN
            SET l_TeamNo = l_Team_nm;
            LEAVE read_loop;
        END IF;
    END LOOP;

    
    CLOSE order_cursor;

    
    IF l_TeamNo IS NULL THEN
        SET l_TeamNo =1;
    END IF;

    
    IF (l_GameType = 0) THEN
        
        SET l_EventSize = (SELECT event_size FROM tb_events WHERE discipline_id = gameid AND id = EventID);
        SET l_TeamCount = (SELECT COUNT(*) FROM tb_selected_players WHERE game_id = gameid AND Event_ID = EventID AND Venue_id = venueid AND team_nm = l_TeamNo);

        IF (l_TeamCount < l_EventSize) THEN
            VALUES (player_id, player_name, EventID, gameid, venueid, l_TeamNo, gender);
        ELSEIF (l_TeamCount = l_EventSize) THEN
            SET l_TeamNo = (SELECT MAX(team_nm) + 1 FROM tb_selected_players WHERE game_id = gameid AND Event_ID = EventID AND Venue_id = venueid);
            VALUES (player_id, player_name, EventID, gameid, venueid, l_TeamNo, gender);
        END IF;

    ELSEIF (l_GameType = 1) THEN
        
        SET l_EventSize = (SELECT event_size FROM tb_events WHERE discipline_id = gameid AND id = EventID);
        SET l_TeamCount = (SELECT COUNT(*) FROM tb_selected_players WHERE game_id = gameid AND Venue_id = venueid AND team_nm = l_TeamNo AND event_id = EventID);

        IF (l_TeamCount < l_EventSize) THEN
            VALUES (player_id, player_name, EventID, gameid, venueid, l_TeamNo, gender);
        ELSEIF (l_TeamCount = l_EventSize) THEN
            SET l_TeamNo = (SELECT MAX(team_nm) + 1 FROM tb_selected_players WHERE game_id = gameid AND Event_ID = EventID AND Venue_id = venueid);
            VALUES (player_id, player_name, EventID, gameid, venueid, l_TeamNo, gender);
        END IF;
    END IF;
END$$

