CREATE DEFINER=`root`@`10.3.39.14` FUNCTION `generateNewMobileNum` () RETURNS VARCHAR(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci DETERMINISTIC BEGIN
    DECLARE first_digit INT;
    DECLARE remaining_digits BIGINT;
    DECLARE mobile_number VARCHAR(10);

    -- Randomly select first digit: 6, 7, 8, or 9
    SET first_digit = FLOOR(6 + RAND() * 4);

    -- Generate remaining 9 digits
    SET remaining_digits = FLOOR(RAND() * 1000000000);

    -- Combine first digit + remaining digits (pad with zeros if needed)
    SET mobile_number = CONCAT(
        first_digit,
        LPAD(remaining_digits, 9, '0')
    );

    RETURN mobile_number;
END$$

